 public:
  ServiceProxy(std::shared_ptr<ServiceApi> real, Tracer& tracer)
      : real_(std::move(real)), tracer_(tracer) {}
  Response Call(const Request& r) override {          // delegate + policy
    auto span = tracer_.Start("Call");
